var currentdatetime = new Date();

function ShowLoader() {
    jQuery('#dfm-preloader').show();
}

function HideLoader() {
    jQuery('#dfm-preloader').hide();
}

function PingAssetServer_ApiCall() {
    jQuery.post(base_url + 'apps/PingAssetServer_ApiCall', {
        ajax: true,
        version: new Date().toISOString().split('T')[0]
    }).done(function(result) {
        console.log('AssetAllocator_2 Server Ping');
    }).fail(function(jqXHR, textStatus, errorThrown) {
        console.error('API Call failed:', textStatus, errorThrown);
    });
}

function PrintSectionbtn(divName) {
    var printContents = document.getElementById(divName).innerHTML;
    w = window.open();
    w.document.write(printContents);
    w.print();
    w.close();
}

function InsertDragDropSolutions() {
    jQuery("#mysolutions_targetcontent").find(".connectedSortable_drag").draggable({
        containment: "#DontRefreshData"
    });
    jQuery("#mysolutions_targetcontent").find(".connectedSortable_drop").droppable({
        connectWith: ".connectedSortable_drag",
        drop: function(event, ui) {
            var draggableId = ui.draggable.attr("id");
            var userid = ui.draggable.attr("data-userid");
            var droppableId = $(this).attr("id");
            jQuery(this).append(ui.draggable);
            var folderid = ui.draggable.attr('data-fldmid');
            $.ajax({
                method: "POST",
                dataType: 'json',
                url: base_url + '/dashboard/dragganddropsolutions',
                data: 'userid=' + userid + '&draggedID=' + draggableId + '&FolderID=' + folderid + '&droppedID=' + droppableId,
            }).done(function(response) {
                UIkit.notification({ message: response.message, pos: 'bottom-center', status: 'grey', timeout: 1800 });
                window.location.reload();
                jQuery('html, body').animate({ scrollTop: jQuery('#mysolutions_targetcontent').offset().top - 10 });
            });
        }
    });
    jQuery("#mysolutions_targetcontent").find(".connectedSortable_drag").sortable();
    jQuery("#mysolutions_targetcontent").find(".connectedSortable_drag").disableSelection();
}
var dataTableColmn = jQuery('#datatableCommon').DataTable({
    "processing": true,
    "serverSide": true,
    'bInfo': true,
    "pageLength": 20,
    'responsive': true,
    'serverMethod': 'POST',
    'ordering': true,
    'bLengthChange': false,
    'searching': true,
    "language": {
        processing: '<img src="' + base_url + 'assets/dash/pix/ajax-loader.gif" style="margin-left: 40%;">'
    },
    "ajax": base_url + controller + "/" + jQuery('#datatableCommon').attr("data-action") + (jQuery('#datatableCommon').attr("data-mode") != '' ? '?mode=' + jQuery('#datatableCommon').attr("data-mode") : ''),
    'createdRow': function(row, data, dataIndex) {
        if (jQuery('#datatableCommon').attr("data-mode") == 'recent') {
            jQuery(row).find('td:eq(2)').addClass('uk-text-right');
        } else if (jQuery('#datatableCommon').attr("data-mode") == 'teamwithsolutions') {
            jQuery(row).find('td:eq(2)').addClass('uk-text-right');
        } else if (jQuery('#datatableCommon').attr("data-mode") == 'myteam') {
            jQuery(row).find('td:eq(7)').addClass('uk-text-right');
            jQuery(row).find('td:eq(8)').addClass('uk-text-center');
        } else if (jQuery('#datatableCommon').attr("data-mode") == 'assumptions') {
            jQuery(row).find('td:eq(4)').addClass('uk-text-right');
        } else if (jQuery('#datatableCommon').attr("data-mode") == 'rolelists') {
            jQuery(row).find('td:eq(1)').addClass('uk-text-truncate');
            jQuery(row).find('td:eq(4)').addClass('uk-text-center');
            jQuery(row).find('td:eq(5)').addClass('uk-text-right');
        } else if (jQuery('#datatableCommon').attr("data-mode") == 'archived') {
            jQuery(row).find('td:eq(2)').addClass('uk-text-truncate');
            jQuery(row).find('td:eq(3)').addClass('uk-text-right');
        }else if (jQuery('#datatableCommon').attr("data-mode") == 'doccuments') {
            jQuery(row).find('td:eq(2)').addClass('uk-text-right');
            jQuery(row).find('td:eq(4)').addClass('uk-text-center');
            jQuery(row).find('td:eq(3)').addClass('uk-text-right');
        }
    }
});
