function showloader(status) {
    jQuery('#gateway-loader').hide();
    if (jQuery('#gateway-loader').length > 0) {
        if (status == 1) {
            jQuery('#gateway-loader').show();
        } else {
            jQuery('#gateway-loader').hide();
        }
    }
}

function ValidateFormSubmit(formclass, label = '') {
    jQuery(document).off().on("submit", "." + formclass, function(e) {
        e.preventDefault();
        var ajax_save_form = jQuery(this);
        var formaction = ajax_save_form.attr('data-action');
        var getcontroller = ajax_save_form.attr('data-controller');
        if (typeof getcontroller !== 'undefined' && getcontroller !== false) {
            var ActionController = ajax_save_form.attr('data-controller');
        } else {
            var ActionController = controller;
        }
        jQuery.ajax({
            enctype: 'multipart/form-data',
            url: base_url + ActionController + '/' + formaction,
            data: new FormData(this),
            method: 'post',
            dataType: 'json',
            processData: false,
            contentType: false,
            cache: false,
            timeout: 600000,
            secure: true,
            crossDomain: true,
            headers: {
                'Access-Control-Allow-Origin': '*',
            },
            beforeSend: function() {
                showloader(1);
                ajax_save_form.find(":submit").prop('disabled', true);
                ajax_save_form.find(":submit").html('Processing...');
            },
            success: function(response) {
                showloader(0);
                ajax_save_form.find(":submit").prop('disabled', false);
                ajax_save_form.find(":submit").html(label);
                if (response.status) {
                    if (response.apiresponse) {
                        localStorage.setItem('apiresponse_graphcodedecode_' + response.iduserallocator, response.apiresponse);
                    }
                    if (response.successpopup) {
                        Swal.fire({
                            title: '',
                            html: response.message,
                            icon: 'success',
                            showCancelButton: false,
                            confirmButtonText: 'Okay',
                        }).then((result) => {
                            if (result.isConfirmed) {
                                if (response.http_redirect) {
                                    window.location.href = response.http_redirect;
                                } else {
                                    if (response.otpscreen) {
                                        jQuery('#endingmobilenumber').html(response.otpscreen);
                                        UIkit.modal('#otp_regmodel').show();
                                    } else {
                                        window.location.reload();
                                    }
                                }
                            }
                        });
                    } else {
                        if (response.http_redirect) {
                            window.location.href = response.http_redirect;
                        } else {
                            window.location.reload();
                        }
                    }
                } else {
                    sweet_alert('Error', response.message, 'error');
                }
            }
        });
    });
}

function sweet_alert(heading, message, alert_type) {
    Swal.fire(
        heading,
        message,
        alert_type
    );
}

function common_view_modal(action, identifier) {
    var modalwith = jQuery(identifier).attr("data-modalwith");
    var autoid = jQuery(identifier).attr("data-autoid");
    var FolderUniQIDS = jQuery(identifier).attr("data-FolderUniQIDS");
    var FolderPrntQIDS = jQuery(identifier).attr("data-FolderPrntQIDS");
    var fromtype = jQuery(identifier).attr("data-fromtype");
    var frompage = jQuery(identifier).attr("data-frompage");
    if (modalwith) {
        jQuery('#common_view_modalpopup').addClass('uk-modal-container');
    } else {
        jQuery('#common_view_modalpopup').removeClass('uk-modal-container');
    }
    UIkit.modal('#common_view_modalpopup').show();
    if (autoid != '') {
        ShowLoader();
        jQuery.ajax({
            url: base_url + action,
            data: { autoid: autoid, FolderUniQIDS: FolderUniQIDS, FolderPrntQIDS: FolderPrntQIDS, ajax: true, version: currentdatetime, frompage: frompage },
            method: 'GET',
            dataType: 'html',
            success: function(response) {
                HideLoader();
                jQuery('#common_view_modalpopup').html(response);
            }
        });
    } else {
        jQuery('#common_view_modalpopup').html('Missing Parameters , Try to load page again');
    }
}

