function removeFolderSolutions(identifier) {
    var SolRow = jQuery(identifier).attr("data-SolRow");
    var modeltype = jQuery(identifier).attr("data-modeltype");
    var FolderUniQIDS = jQuery(identifier).attr("data-FolderUniQIDS");
    var isarchived = jQuery(identifier).attr("data-isarchived");
    var frompage = jQuery(identifier).attr("data-frompage");
    if (SolRow != '') {
        jQuery.ajax({
            url: base_url + controller + '/removesolutions',
            data: { SolRow: SolRow, modeltype: modeltype, UniQIDS: FolderUniQIDS, ajax: true, version: new Date(), isarchived: isarchived, fromtype: 'othertab' },
            method: 'post',
            dataType: 'json',
            beforeSend: function() {
                jQuery(this).prop('disabled', true);
                jQuery(this).html('Processing...');
            },
            success: function(response) {
                if (response.status) {
                    Swal.fire({
                        title: '',
                        html: response.message,
                        icon: '',
                        showCancelButton: false,
                        confirmButtonText: 'Okay',
                    }).then((result) => {
                        if (result.isConfirmed) {
                            UIkit.modal('#common_view_modalpopup').hide();
                            if (frompage == 'recentpage') {
                                //UIkit.notification({message: response.message, pos: 'top-right',status: 'success'});
                                dataTableColmn.draw();
                            } else {
                                window.location.reload();
                            }
                        }
                    });
                } else {
                    sweet_alert('Error', response.message, 'error');
                }
            }
        });
    }
}

function DuplicateSolutions(identifier) {
    var ModelType = jQuery(identifier).attr("data-modeltype");
    var userid = jQuery(identifier).attr("data-userid");
    var SolRow = jQuery(identifier).attr("data-SolRow");
    var FolderUniQIDS = jQuery(identifier).attr("data-FolderUniQIDS");
    var FolderPrntQIDS = jQuery(identifier).attr("data-FolderPrntQIDS");
    var fromtype = jQuery(identifier).attr("data-fromtype");
    if (SolRow != '') {
        UIkit.modal.confirm('Are you sure you want to create duplicate of solution/folder. <br><br> Select Confirm to duplicate or Cancel.', { labels: { ok: 'Confirm', cancel: 'Cancel' } }).then(function() {
            jQuery.ajax({
                url: base_url + '/dashboard/makeduplicatesolution',
                data: { userid: userid, ModelType: ModelType, SolRow: SolRow, FolderPrntQIDS: FolderPrntQIDS, FolderUniQIDS: FolderUniQIDS, fromtype, fromtype, ajax: true, version: new Date() },
                method: 'post',
                dataType: 'json',
                success: function(response) {
                    //UIkit.notification({message: response.message, pos: 'top-right',status: 'success'});
                    if (response.status) {
                        if (fromtype == 'recent') {
                            dataTableColmn.draw();
                        } else {
                            window.location.reload();
                        }
                    }
                }
            });
        }, function() {
            console.log('Rejected.');
        });
    }
}

